UPDATE risk_knowledge_entries SET problem_json='{"statement":"Support staff, administrators or agents can impersonate users without scoped purpose, consent, expiry or audit.","customer_symptom":"A user or operator may observe support staff, administrators or agents can impersonate users without scoped purpose, consent, expiry or audit; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"An operator, service or compromised AI agent may assume another subject identity or forward a delegated authorization outside its approved actor, tenant, resource, operation, purpose, privilege ceiling or validity window, allowing unauthorized downstream action or disclosure.","affected_assets":["agent","model context","tools or downstream systems","customer evidence"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["platforms with support or delegation"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"Between initiating actor, delegated subject and each service, MCP/tool, job, API and audit enforcement point that must independently verify authority before effect.","operational_impact":"If support staff, administrators or agents can impersonate users without scoped purpose, consent, expiry or audit, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-030 impersonation, delegation, support-session or delegated-approval change","ARL-KB-030 target visibility, privilege ceiling, expiry or termination-control change","ARL-KB-030 delegation abuse, impersonation bypass or unattributable support-action incident","ARL-KB-030 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"candidate semantic correction; independent practitioner and customer validation required"}', content_digest='aea8e4ac84e8caddc74039f0a983177a470dbb0dd4572d12c6a854a571a49872', updated_at='2026-10-12' WHERE id='ARL-KB-030';
UPDATE risk_knowledge_checks SET objective='Determine whether impersonation and delegated authority remain explicitly approved, scoped, time-bounded, independently enforced, revocable and attributable on the exact assessed build.', method='Review owner-approved impersonation and delegation policy and version-bound enforcement. With separate written owner authorization, run bounded synthetic same-tenant allowed scenarios plus wrong-actor, wrong-subject, cross-tenant, privilege escalation, missing approval, replay, expired/revoked and queued-work scenarios. Correlate responses, tool/job effects and audit lineage.', required_evidence_json='["ARL-KB-030 exact frozen build SHA, deployed environment, identity and tenant scope, delegated endpoints, agent/tool/MCP gateways, queues, jobs and audit sinks","ARL-KB-030 approved actor/delegate/subject, tenant, operation and resource policy with purpose, consent or authorised exception as applicable, privilege ceiling, expiry, revocation and accountable policy owner","ARL-KB-030 version-bound source and configuration of independent actor and subject identity, receiving-end authorization, approval binding, scoped delegation, session visibility, replay prevention, worker enforcement and fail-closed expiry","ARL-KB-030 bounded positive synthetic staging evidence of owner-authorised delegation and termination, approved scope, expected outputs and downstream changes","ARL-KB-030 bounded negative synthetic staging evidence of missing approval, wrong actor or subject, wrong tenant, scope escalation, self-approval, expired or revoked delegation, replay, queued job and direct gateway bypass denied before disclosure or effects","ARL-KB-030 correlated runtime evidence of initiator, subject, purpose, policy digest, approval, tenant, authorization decision, tool/worker execution, relevant response and before/after state with attributable audit records","ARL-KB-030 written owner authorisation, tester and independent reviewer role, exact version and evidence digest, exceptions, unsupported paths, limitations and accountable human conclusion"]', pass_condition='KB-030 passes only after accountable human review of the exact build, approved actor/subject delegation and privilege ceiling, bounded synthetic allowed and denied scenarios, expiration and revocation, and correlated runtime evidence showing no unauthorized data disclosure or downstream effect on applicable scoped paths.', fail_condition='KB-030 is a confirmed FAIL only when exact-version corroborated evidence demonstrates unauthorized impersonation, cross-tenant delegation, scope escalation, forbidden disclosure or downstream effect, or an executable delegation path that demonstrably fails open. Missing owner policy, exact-version tests, runtime correlation or accountable signoff require INCONCLUSIVE / EVIDENCE GAP / REVIEW REQUIRED: block PASS and deployment without claiming a confirmed vulnerability.', content_digest='9509a7ba6709c434cd7b449281ec1069e31f69b3e2dd6e24b803e1ff9c1214e9', updated_at='2026-10-12' WHERE entry_id='ARL-KB-030';
UPDATE risk_knowledge_solutions SET retest_acceptance_json='["ARL-KB-030: Exact remediated build, delegated actor/subject policy, scope, tenant, exception conditions and digests are recorded.","ARL-KB-030: Written owner-authorized synthetic permitted impersonation and delegation actions remain within scope with expected response and attributable downstream audit.","ARL-KB-030: Synthetic wrong actor, subject, tenant, privilege, approval, replay, revoked and expired variants fail closed before disclosure or side effect across applicable service and queued paths.","ARL-KB-030: Accountable human reviewer records exact-version retest evidence, exceptional modes, unsupported paths, limitations and final decision."]', content_digest='b3fbc52d4beb55c7a3b8795d4ee421eccb82bd2167928a3c169b85c4b1976b1f', updated_at='2026-10-12' WHERE entry_id='ARL-KB-030';
